const store = $getWorkflowStaticData('global');
store["transakcje"] = store["transakcje"] || {};
const seen = store["transakcje"];
const now = Date.now();
const ttl = 400 * 86400000;
for (const [k, t] of Object.entries(seen)) if (now - t > ttl) delete seen[k];
const out = [];
$input.all().forEach((item, index) => {
  const key = String(item.json.id ?? '');
  if (!key || seen[key]) return; // brak klucza albo już obsłużone -> pomiń
  // pairedItem zachowuje powiązanie z danymi wejściowymi (potrzebne dla odwołań .item w kolejnych węzłach)
  out.push({ json: item.json, binary: item.binary, pairedItem: { item: index } });
});
return out;

const SYSTEM = "Przypisujesz transakcję bankową do jednej kategorii kosztowej z podanej listy.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"kategoria\": jedna z listy, \"pewnosc\": liczba 0-1}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Kategorie: ${$('Konfiguracja').first().json.kategorie}\nKontrahent: ${$json.counterparty}\nTytuł: ${$json.title}\nKwota: ${$json.amount}`;
return {
  json: {
    ...$json,
    _aiPrompt: String(user).slice(0, 12000),
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (kategoria kosztu)').item.json };
delete ctx._aiPrompt;
let out = {};
let aiError = '';
try {
  const raw = $json.output ?? '';
  out = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"kategoria":"","pewnosc":0};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);
out.pewnosc = Math.max(0, Math.min(1, Number(out.pewnosc)));
if (!Number.isFinite(out.pewnosc)) out.pewnosc = 0;
return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };

